<script lang="ts">import { onMount } from 'svelte'; import { api } from '$lib/api'; import JobTable from './JobTable.svelte'; let data = $state<any>(null); let error = $state(''); onMount(async () => { try { data = await api('/dashboard/summary'); } catch (e) { error = e instanceof Error ? e.message : 'Gagal memuat ringkasan.'; } });</script>
<header><p class="text-sm font-bold tracking-[.2em] text-indigo-300">RINGKASAN</p><h1 class="mt-2 text-3xl font-black">Control center</h1><p class="muted mt-2">Status gateway, antrean, storage, dan backup.</p></header>{#if error}<p class="mt-5 text-rose-300">{error}</p>{/if}<div class="mt-7 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{#each Object.entries(data || {}) as [key, value]}<section class="card p-5"><p class="muted capitalize">{key.replaceAll('_', ' ')}</p><pre class="mt-3 whitespace-pre-wrap text-sm">{JSON.stringify(value, null, 2)}</pre></section>{/each}</div><JobTable title="Job terbaru" />
